import React, { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import { getCategoryProducts } from '../services/api';
import SearchBarUnified from '../components/SearchBarUnified';

export default function CategoryPage() {
  const { id } = useParams();
  const [cat, setCat] = useState(null);
  const [items, setItems] = useState([]);

  // productos de la categoría
  useEffect(() => {
    (async () => {
      const prods = await getCategoryProducts(id);
      setItems(prods || []);
    })();
  }, [id]);

  // datos de la categoría (para título + banner)
  useEffect(() => {
    (async () => {
      try {
        const res = await fetch('/api/categories');
        const all = await res.json();
        const c = (all || []).find((x) => String(x.id) === String(id));
        setCat(c || null);
      } catch {
        setCat(null);
      }
    })();
  }, [id]);

  const priceFmt = (n) =>
    typeof n === 'number' ? n.toLocaleString('es-AR') : '';

  const banner = cat?.imageBanner || cat?.imageUrl || '';

  return (
    <div className="cp-cat">
      {/* Banner */}
      <section
        className="hero"
        style={banner ? { backgroundImage: `url(${banner})` } : {}}
        aria-label={cat?.name || `Categoría #${id}`}
      >
        <div className="hero-layer">
          {/* Banda amarilla con logo + título centrado */}
          <div className="brand-badge">
            <img
              src="/logo.png"
              alt="Conecta Pinamar"
              className="brand-logo"
              id="logoc"
            />
          </div>
          <h1 className="title">{(cat?.name || 'Categoría').toUpperCase()}</h1>

          {/* Buscador unificado reutilizado */}
          <div className="search-holder">
            <SearchBarUnified />
          </div>
        </div>
      </section>

      {/* Grilla de productos */}
      <div className="grid">
        {items.map((p) => (
          <a key={p.id} className="card" href={`/producto/${p.id}`}>
            <div className="thumb">
              <img src={p.imageUrl} alt={p.name} loading="lazy" />
            </div>
            <div className="meta">
              <div className="name">{p.name || 'producto'}</div>
              <div className="price">
                {typeof p.price !== 'undefined' ? `$ ${priceFmt(p.price)}` : '$'}
              </div>
            </div>
          </a>
        ))}
        {!items?.length && (
          <div className="empty">No hay productos en esta categoría.</div>
        )}
      </div>

      {/* Estilos embebidos para que calce con el mock y con SearchBarUnified */}
      <style>{`
        .cp-cat{
          --yellow:#F7D34A;
          --ink:#111;
          --card:#fff;
          --border:#e6e6e6;
          --shadow:0 8px 24px rgba(0,0,0,.08);
        }

        .hero{
          position:relative; width:100%;
          min-height:260px;
          background:#ddd center/cover no-repeat;
          display:grid; place-items:center;
          padding:20px 16px 64px;
        }
        .hero::after{
          content:""; position:absolute; inset:0;
          background:linear-gradient(180deg, rgba(0,0,0,.20), rgba(0,0,0,.35));
        }
        .hero-layer{
          position:relative; z-index:1;
          width:100%; max-width:1100px;
          display:flex; flex-direction:column;
          align-items:center; gap:12px;
        }

        /* Banda amarilla + logo centrado */
        .brand-badge{
          background:var(--yellow),0.5;
          border-radius:10px;
          padding:6px 10px;
          display:flex; align-items:center; justify-content:center;
          box-shadow:0 8px 18px rgba(0,0,0,.15);

        }
        .brand-logo{ height:72px; display:block; }
        #logoc{height:72px;}

        .title{
          margin:0;
          color:#fff;
          text-align:center;
          text-shadow:0 2px 8px rgba(0,0,0,.35);
          font:800 32px/1.05 system-ui,-apple-system,Segoe UI,Roboto,Ubuntu,Cantarell,Noto Sans,sans-serif;
          letter-spacing:.5px;
        }

        /* Contenedor para adaptar SearchBarUnified al banner */
        .search-holder{
          width:100%; max-width:700px;
          margin-top:4px;
        }

        /* “Piel” visual para SearchBarUnified (sin tocar su lógica) */
        .cp-search-wrap{
          position:relative; width:100%;
          background:#fff;
          border:2px solid var(--yellow);
          border-radius:999px;
          padding:6px;
          box-shadow:0 4px 18px rgba(0,0,0,.1);
        }
        .cp-search-input{
          width:100%; border:0; outline:none;
          font-size:14px; padding:8px 12px;
          background:transparent; color:#111;
        }
        .cp-search-panel{
          position:absolute; left:0; right:0; top:100%; margin-top:8px;
          background:#fff; border:1px solid #ececec; border-radius:14px;
          box-shadow:0 14px 32px rgba(0,0,0,.18); overflow:hidden; z-index:5;
          max-height:340px; overflow-y:auto;
        }
        .cp-search-item{
          display:flex; align-items:center; gap:10px;
          padding:10px 12px; text-decoration:none; color:#111;
        }
        .cp-search-item:hover{ background:#fafafa; }
        .cp-search-item .thumb{
          width:42px; height:32px; object-fit:cover;
          border-radius:6px; border:1px solid #eee; background:#f6f6f6;
        }
        .cp-search-item .b{ font-weight:700; }
        .cp-search-item .i{ font-style:italic; }

        /* Grilla de cards */
        .grid{
          max-width:1100px; margin:24px auto; padding:0 16px 32px;
          display:grid; grid-template-columns:repeat(auto-fill, minmax(180px, 1fr));
          gap:18px;
        }
        .card{
          display:flex; flex-direction:column;
          background:var(--card); border:1px solid var(--border);
          border-radius:16px; text-decoration:none; color:var(--ink);
          box-shadow:var(--shadow);
          transition:transform .12s ease, box-shadow .12s ease;
        }
        .card:hover{ transform:translateY(-2px); box-shadow:0 10px 26px rgba(0,0,0,.12); }
        .thumb{ aspect-ratio:1/1; width:100%; overflow:hidden; border-top-left-radius:16px; border-top-right-radius:16px; }
        .thumb img{ width:100%; height:100%; object-fit:cover; display:block; }
        .meta{ padding:10px 12px 12px; }
        .name{ font-weight:800; font-size:18px; line-height:1.1; margin:0 0 6px 0; }
        .price{ font-weight:900; font-size:20px; }
        .empty{ grid-column:1 / -1; text-align:center; color:#666; padding:24px 0; }

        @media (min-width:900px){
          .hero{ min-height:320px; padding:28px 16px 90px; }
          .brand-logo{ height:24px; }
          .title{ font-size:40px; }
          .grid{ gap:22px; }
          .name{ font-size:20px; }
          .price{ font-size:22px; }
        }
      `}</style>
    </div>
  );
}
